chunk.argumentsDelta:
{"file_path":"src/nodes.js","content":"// Node constructors for the document tree.

export function makeTable() {
  return { kind: 'table', entries: new Map(), headerDefined: false }
}

export function makeAot() {
  return { kind: 'aot', items: [] }
}

export function makeArray(items) {
  return { kind: 'array', items }
}

export function makeString(value) {
  return { kind: 'string', value }
}

export function makeInteger(value) {
  return { kind: 'integer', value }
}

export function makeFloat(value) {
  return { kind: 'float', value }
}

export function makeBoolean(value) {
  return { kind: 'boolean', value }
}

export function formatPath(segments) {
  let out = ''
  for (const seg of segments) {
    if (seg.type === 'key') {
      out += (out.length ? '.' : '') + seg.name
    } else {
      out += `[${seg.i}]`
    }
  }
  return out
}

export function compareCodePoints(a, b) {
  const A = Array.from(a)
  const B = Array.from(b)
  const len = Math.min(A.length, B.length)
  for (let i = 0; i < len; i++) {
    const ca = A[i].codePointAt(0)
    const cb = B[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return A.length - B.length
}
"}

