        return { value: out, pos }
      }
      if (c === '\\') {
        pos++
        if (pos >= this.len) this.fail('unterminated string')
        const e = this.line[pos]
        if (e === '"') { out += '"'; pos++ }
        else if (e === '\\') { out += '\\'; pos++ }
        else if (e === 'n') { out += '\n'; pos++ }
        else if (e === 't') { out += '\t'; pos++ }
        else if (e === 'r') { out += '\r'; pos++ }
        else if (e === '0') { out += '\0'; pos++ }
        else if (e === 'u') {
          pos++
          if (pos + 4 > this.len) this.fail('unterminated string')
          const hex = this.line.slice(pos, pos + 4)
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) this.fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          pos += 4
        } else {
          this.fail(`invalid escape \\${e}`)
        }
        continue
      }
      out += c
      pos++
    }
  }

  parseLiteralStringRaw(pos) {
    pos++
    let out = ''
    for (;;) {
      if (pos >= this.len) this.fail('unterminated string')
      const c = this.line[pos]
      if (c === "'") {
        pos++
        return { value: out, pos }
      }
      out += c
      pos++
    }
  }

  // Parses a value at pos with the given basePath (array of segment objects,
  // used to build absolute paths for nested conflicts). Returns { node, pos }.
  parseValue(pos, basePath) {
    pos = this.skipSpacesAndComment(pos)
    if (pos >= this.len) this.fail('expected a value')
    const c = this.line[pos]
    if (c === ',' || c === ']' || c === '}') this.fail('expected a value')
    if (c === '"') {
      const r = this.parseBasicStringRaw(pos)
      return { node: makeString(r.value), pos: r.pos }
    }
    if (c === "'") {
      const r = this.parseLiteralStringRaw(pos)
      return { node: makeString(r.value), pos: r.pos }
    }
    if (c === '[') return this.parseArray(pos, basePath)
    if (c === '{') return this.parseInlineTable(pos, basePath)
    const start = pos
    while (pos < this.len && !isSpace(this.line[pos]) && this.line[pos] !== ',' &&
           this.line[pos] !== ']' && this.line[pos] !== '}') {
      pos++
    }
    const token = this.line.slice(start, pos)
    if (token === 'true') return { node: makeBoolean(true), pos }
    if (token === 'false') return { node: makeBoolean(false), pos }
    if (INT_RE.test(token)) {
      const sign = token[0] === '+' ? '' : (token[0] === '-' ? '-' : '')
      let digits = token
      if (token[0] === '+' || token[0] === '-') digits = token.slice(1)
      digits = digits.replace(/_/g, '')
      const value = BigInt((sign === '-' ? '-' : '') + digits)
      return { node: makeInteger(value), pos }
    }
    if (FLOAT_RE.test(token)) {
      const value = Number(token.replace(/_/g, ''))
      return { node: makeFloat(value), pos }
    }
    this.fail(`invalid value ${token}`)
  }

  parseArray(pos, basePath) {
    pos++ // consume '['
    const items = []
    pos = this.skipSpacesAndComment(pos)
    if (pos >= this.len) this.fail('unterminated array')
    if (this.line[pos] === ']') {
      pos++
      return { node: makeArray(items), pos }
    }
    let index = 0
    for (;;) {
      const r = this.parseValue(pos, basePath.concat([{ type: 'index', i: index }]))
      items.push(r.node)
      pos = r.pos
      index++
      pos = this.skipSpacesAndComment(pos)
      if (pos >= this.len) this.fail('unterminated array')
      const c = this.line[pos]
      if (c === ',') {
        pos++
        pos = this.skipSpacesAndComment(pos)
        if (pos >= this.len) this.fail('unterminated array')
        if (this.line[pos] === ']') {
          pos++
          break
        }
        continue
      } else if (c === ']') {
        pos++
        break
      } else {
        this.fail('trailing text after a value')
      }
    }
    return { node: makeArray(items), pos }
  }

  parseInlineTable(pos, basePath) {
    pos++ // consume '{'
    const table = makeTable()
    pos = this.skipSpacesAndComment(pos)
    if (pos >= this.len) this.fail('unterminated inline table')
    if (this.line[pos] === '}') {
      pos++
      return { node: table, pos }
    }
    for (;;) {
      const n = this.parseDottedName(pos)
      pos = this.skipSpacesAndComment(n.pos)
      if (pos >= this.len) this.fail('unterminated inline table')
      if (this.line[pos] !== '=') this.fail('expected = in an inline table')
      pos++
      const r = this.parseValue(pos, basePath.concat(n.segments.map((s) => ({ type: 'key', name: s }))))
      pos = r.pos
      this.insertPath(table, n.segments, r.node, basePath)
      pos = this.skipSpacesAndComment(pos)
      if (pos >= this.len) this.fail('unterminated inline table')
      const c = this.line[pos]
      if (c === ',') {
        pos++
        pos = this.skipSpacesAndComment(pos)
        if (pos >= this.len) this.fail('unterminated inline table')
        if (this.line[pos] === '}') this.fail('expected a name')
        continue
      } else if (c === '}') {
        pos++
        break
      } else {
        this.fail('trailing text after a value')
      }
    }
    return { node: table, pos }
  }

  // Inserts `value` at `pathSegments` (array of strings) inside `rootTable`,
  // creating intermediate tables. `basePath` is the absolute path of rootTable.
  insertPath(rootTable, pathSegments, value, basePath) {
    let current = rootTable
    const accumulated = basePath.slice()
    for (let i = 0; i < pathSegments.length; i++) {
      const seg = pathSegments[i]
      accumulated.push({ type: 'key', name: seg })
      const isLast = i === pathSegments.length - 1
      const existing = current.entries.get(seg)
      if (isLast) {
        if (existing !== undefined) this.fail(`key ${formatPath(accumulated)} is defined twice`)
        current.entries.set(seg, value)
      } else if (existing === undefined) {
        const t = makeTable()
        current.entries.set(seg, t)
        current = t
      } else if (existing.kind === 'table') {
        current = existing
      } else if (existing.kind === 'aot') {
        current = existing.items[existing.items.length - 1]
      } else {
        this.fail(`${formatPath(accumulated)} is not a table`)
      }
    }
  }
}

// Walks/creates tables for all but the last of `segments`, starting at `root`.
// Returns { table, accumulated } where `table` is the table to act on for the
// last segment, and `accumulated` is the path up to (not including) it.
function walkIntermediate(lp, root, segments, basePath) {
  let current = root
  const accumulated = basePath.slice()
  for (let i = 0; i < segments.length - 1; i++) {
    const seg = segments[i]
    accumulated.push({ type: 'key', name: seg })
    const existing = current.entries.get(seg)
    if (existing === undefined) {
      const t = makeTable()
      current.entries.set(seg, t)
      current = t
    } else if (existing.kind === 'table') {
      current = existing
    } else if (existing.kind === 'aot') {
      current = existing.items[existing.items.length - 1]
    } else {
      lp.fail(`${formatPath(accumulated)} is not a table`)
    }
  }
  return { table: current, accumulated }
}

function handleHeader(lp, root, isAot, segments) {
  const { table, accumulated } = walkIntermediate(lp, root, segments, [])
  const name = segments[segments.length - 1]
  accumulated.push({ type: 'key', name })
  const existing = table.entries.get(name)
  if (!isAot) {
    if (existing === undefined) {
      const t = makeTable()
      t.headerDefined = true
      table.entries.set(name, t)
      return { current: t, path: accumulated }
    } else if (existing.kind === 'table') {
      if (existing.headerDefined) lp.fail(`table ${formatPath(accumulated)} is defined twice`)
      existing.headerDefined = true
      return { current: existing, path: accumulated }
    } else {
      lp.fail(`${formatPath(accumulated)} is not a table`)
    }
  } else {
    if (existing === undefined) {
      const aot = makeAot()
      const t = makeTable()
      aot.items.push(t)
      table.entries.set(name, aot)
      return { current: t, path: accumulated }
    } else if (existing.kind === 'aot') {
      const t = makeTable()
      existing.items.push(t)
      return { current: t, path: accumulated }
    } else {
      lp.fail(`${formatPath(accumulated)} is not an array of tables`)
    }
  }
}

export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeTable()
  let currentTable = root
  let currentPath = []

  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1
    const line = lines[idx]
    const len = line.length
    let start = 0
    while (start < len && isSpace(line[start])) start++
    if (start >= len) continue
    if (line[start] === '#' || line[start] === ';') continue

    const lp = new LineParser(line, lineNo)

    if (line[start] === '[') {
      let pos = start + 1
      let isAot = false
      if (pos < len && line[pos] === '[') {
        isAot = true
        pos++
      }
      const n = lp.parseDottedName(pos)
      pos = n.pos
      if (isAot) {
        if (pos >= len || line[pos] !== ']' || pos + 1 >= len || line[pos + 1] !== ']') {
          lp.fail('unterminated table header')
        }
        pos += 2
      } else {
        if (pos >= len || line[pos] !== ']') {
          lp.fail('unterminated table header')
        }
        pos += 1
      }
      pos = lp.skipSpacesAndComment(pos)
      if (pos < len) lp.fail('trailing text after a table header')

      const result = handleHeader(lp, root, isAot, n.segments)
      currentTable = result.current
      currentPath = result.path
      continue
    }

    // key = value
    const n = lp.parseDottedName(start)
    let pos = lp.skipSpacesAndComment(n.pos)
    if (pos >= len || line[pos] !== '=') lp.fail('expected key = value')
    pos++
    const r = lp.parseValue(pos, currentPath)
    pos = lp.skipSpacesAndComment(r.pos)
    if (pos < len) lp.fail('trailing text after a value')
    lp.insertPath(currentTable, n.segments, r.node, currentPath)
  }

  return root
}
"}

