{"file_path":"src/format.js","content":"import { compareCodePoints, formatPath } from './nodes.js'

function sortedKeys(table) {
  return [...table.entries.keys()].sort(compareCodePoints)
}

function stringifyValue(node, indent) {
  const pad = '  '.repeat(indent)
  const padIn = '  '.repeat(indent + 1)
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const lines = keys.map(
        (k) => `${padIn}${JSON.stringify(k)}: ${stringifyValue(node.entries.get(k), indent + 1)}`
      )
      return `{\n${lines.join(',\n')}\n${pad}}`
    }
    case 'aot':
    case 'array': {
      const items = node.items
      if (items.length === 0) return '[]'
      const lines = items.map((it) => `${padIn}${stringifyValue(it, indent + 1)}`)
      return `[\n${lines.join(',\n')}\n${pad}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'integer':
      return node.value.toString()
    case 'float':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

export function toJSON(root) {
  return stringifyValue(root, 0) + '\n'
}

function typeOf(node) {
  switch (node.kind) {
    case 'table': return 'table'
    case 'aot':
    case 'array': return 'array'
    case 'string': return 'string'
    case 'integer': return 'integer'
    case 'float': return 'float'
    case 'boolean': return 'boolean'
    default: throw new Error(`unknown node kind ${node.kind}`)
  }
}

export function toKeys(root) {
  const out = []
  function walk(node, path) {
    if (node.kind === 'table') {
      for (const k of sortedKeys(node)) {
        const child = node.entries.get(k)
        const childPath = path.concat([{ type: 'key', name: k }])
        out.push(`${formatPath(childPath)} ${typeOf(child)}`)
        walk(child, childPath)
      }
    } else if (node.kind === 'aot' || node.kind === 'array') {
      node.items.forEach((child, i) => {
        const childPath = path.concat([{ type: 'index', i }])
        out.push(`${formatPath(childPath)} ${typeOf(child)}`)
        walk(child, childPath)
      })
    }
  }
  walk(root, [])
  return out.length ? out.join('\n') + '\n' : ''
}
"}

